$ErrorActionPreference = "Stop"

$projectRoot = Split-Path -Parent $PSScriptRoot

$brainActionsPath = Join-Path $projectRoot "lib\brain-actions.ts"
$actionsRoutePath = Join-Path $projectRoot "app\api\brain\actions\route.ts"
$commandRoutePath = Join-Path $projectRoot "app\api\brain\command\route.ts"
$commandUiPath = Join-Path $projectRoot "app\components\AssistantCommandBar.tsx"

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $commandRoutePath) | Out-Null

$brainActions64 = ""
$actionsRoute64 = ""
$commandRoute64 = ""
$commandUi64 = ""

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($path in @($brainActionsPath, $actionsRoutePath, $commandRoutePath, $commandUiPath)) {
    if (Test-Path -LiteralPath $path) {
        Copy-Item -LiteralPath $path -Destination ($path + ".bak-12-81-" + $timestamp) -Force
    }
}

function WriteDecoded {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [string]$Base64
    )

    $bytes = [Convert]::FromBase64String($Base64)
    [System.IO.File]::WriteAllBytes($Path, $bytes)
}

WriteDecoded -Path $brainActionsPath -Base64 $brainActions64
WriteDecoded -Path $actionsRoutePath -Base64 $actionsRoute64
WriteDecoded -Path $commandRoutePath -Base64 $commandRoute64
WriteDecoded -Path $commandUiPath -Base64 $commandUi64

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.81 APPLIQUE"
Write-Host "======================================"
Write-Host "Actions calculees cote serveur."
Write-Host "Route actions mutualisee."
Write-Host "Route commande ne fait plus confiance au navigateur."
Write-Host "Aucune action sensible executee automatiquement."
Write-Host ""
